/** Rotate a cell within its 2x2 platform: (0,0)->(0,1)->(1,1)->(1,0). */
function rotateCellInPlatform(localRow, localCol, quarters) {
  let r = localRow;
  let c = localCol;
  for (let i = 0; i < (((quarters % 4) + 4) % 4); i++) {
    const nr = c;
    const nc = 1 - r;
    r = nr;
    c = nc;
  }
  return { row: r, col: c };
}

