function spawnBalls(match) {
  if (!SPAWN_TICKS.includes(match.tick)) return [];

  const spawned = [];
  const occupied = new Set(
    match.balls.map((ball) => `${ball.row},${ball.col}`),
  );
  for (const [sourceIndex, source] of SOURCES.entries()) {
    const cell = `${source.row},${source.col}`;
    if (occupied.has(cell)) continue;

    const mask = match.cells[source.row][source.col];
    // Reserve the id first — the draw uses it, so both sources roll apart.
    const id = match.nextBallId;
    const exit = pickSpawnExit(mask, source, match.tick, sourceIndex, id);
    if (exit === undefined) continue;
    match.nextBallId++;

    const ball = {
      id,
      row: source.row,
      col: source.col,
      exit,
    };
    match.balls.push(ball);
    occupied.add(cell);
    // The view animates the ball rising from this cell.
    spawned.push({ id: ball.id, row: ball.row, col: ball.col });
  }
  return spawned;
}

/** Move every ball one cell at most, read from one snapshot so order cannot matter. */
function moveBalls(match) {
  const moves = [];
  const delivered = [];

  const prepareBounce = (ball, reason) => {
    const mask = match.cells[ball.row][ball.col];
    ball.pendingBounceExit = otherPort(mask, ball.exit);
    ball.pendingBounceReason = reason;
  };

  for (const ball of match.balls) {
    const mask = match.cells[ball.row][ball.col];

    // A ball whose exit no longer exists on its own piece waits in place.
    if (!(mask & (1 << ball.exit))) {
      continue;
    }

    const nr = ball.row + DR[ball.exit];
    const nc = ball.col + DC[ball.exit];

    // Leaving through the top or bottom edge is a delivery.
    if (nr < 0 || nr >= SIZE) {
      const side = nr < 0 ? "top" : "bottom";
      delivered.push({ id: ball.id, side, from: { row: ball.row, col: ball.col } });
      moves.push({ id: ball.id, kind: "deliver", side });
      continue;
    }

    // A closed side wall is still a dead end: recoil rather than wait forever.
    if (nc < 0 || nc >= SIZE) {
      prepareBounce(ball, "dead-end");
      continue;
    }

    const entryPort = (ball.exit + 2) % 4;
    const targetMask = match.cells[nr][nc];

    if (!(targetMask & (1 << entryPort))) {
      // Track ends inside the board: stay put, leave by this piece's other end.
      prepareBounce(ball, "dead-end");
      continue;
    }

    ball.pendingRow = nr;
    ball.pendingCol = nc;
    ball.pendingExit = otherPort(targetMask, entryPort);
  }

  // One ball per cell. Repeated to a fixed point rather than resolved in one
  // pass, so the result cannot depend on array order — both peers must agree.
  // A blocked ball stays put and reverses along its track.
  const deliveredIdSet = new Set(delivered.map((d) => d.id));

  for (let changed = true; changed; ) {
    changed = false;

    // Cells still occupied after this step.
    const occupied = new Set();
    for (const ball of match.balls) {
      if (deliveredIdSet.has(ball.id)) continue;
      if (ball.pendingRow !== undefined) continue;
      occupied.add(`${ball.row},${ball.col}`);
    }

    // Two balls may not land on the same cell either.
    const claims = new Map();
    for (const ball of match.balls) {
      if (ball.pendingRow === undefined) continue;
      const key = `${ball.pendingRow},${ball.pendingCol}`;
      if (!claims.has(key)) claims.set(key, []);
      claims.get(key).push(ball);
    }

    // Adjacent balls heading into each other collide instead of swapping.
    const origins = new Map();
    for (const ball of match.balls) {
      if (!deliveredIdSet.has(ball.id)) origins.set(`${ball.row},${ball.col}`, ball);
    }
    const swaps = new Set();
    for (const ball of match.balls) {
      if (ball.pendingRow === undefined) continue;
      const occupant = origins.get(`${ball.pendingRow},${ball.pendingCol}`);
      if (occupant?.pendingRow === ball.row && occupant?.pendingCol === ball.col) {
        swaps.add(ball.id);
        swaps.add(occupant.id);
      }
    }

    for (const ball of match.balls) {
      if (ball.pendingRow === undefined) continue;
      const key = `${ball.pendingRow},${ball.pendingCol}`;

      const blockedByStaying = occupied.has(key);
      // Contested cell: nobody takes it. A winner would need a tie-break both
      // peers agree on, and standing still is what the rest of the rules do.
      const contested = (claims.get(key) || []).length > 1;
      const swapping = swaps.has(ball.id);

      if (blockedByStaying || contested || swapping) {
        prepareBounce(ball, "collision");
        delete ball.pendingRow;
        delete ball.pendingCol;
        delete ball.pendingExit;
        changed = true;
      }
    }
  }

  // Record what actually happens, now that blocking is settled.
  for (const ball of match.balls) {
    if (deliveredIdSet.has(ball.id)) continue;
    if (ball.pendingRow === undefined) {
      moves.push(ball.pendingBounceExit === undefined
        ? { id: ball.id, kind: "wait" }
        : { id: ball.id, kind: "bounce", reason: ball.pendingBounceReason,
            at: { row: ball.row, col: ball.col } });
    } else {
      moves.push({
        id: ball.id,
        kind: "move",
        from: { row: ball.row, col: ball.col },
        to: { row: ball.pendingRow, col: ball.pendingCol },
      });
    }
  }

  // Apply after every ball has been read.
  for (const ball of match.balls) {
    if (ball.pendingRow !== undefined) {
      ball.row = ball.pendingRow;
      ball.col = ball.pendingCol;
      ball.exit = ball.pendingExit;
      delete ball.pendingRow;
      delete ball.pendingCol;
      delete ball.pendingExit;
    } else if (ball.pendingBounceExit !== undefined) {
      ball.exit = ball.pendingBounceExit;
    }
    delete ball.pendingBounceExit;
    delete ball.pendingBounceReason;
  }

  const deliveredIds = new Set(delivered.map((d) => d.id));
  for (const d of delivered) {
    match.score[d.side] += 1;
  }
  match.balls = match.balls.filter((ball) => !deliveredIds.has(ball.id));

  // No lifetime: a ball leaves only by delivery. `expired` stays in the event
  // shape because the view and the replay still read the field.
  const expired = [];

  return { moves, delivered, expired };
}

/** Resolve one tick; returns an event record for animation and replay. */
function resolveTick(match, topCommand, bottomCommand) {
  if (match.finished) return null;

  match.tick += 1;

  const commands = { top: topCommand ?? null, bottom: bottomCommand ?? null };

  // Reject anything illegal rather than trusting the peer.
  for (const side of ["top", "bottom"]) {
    if (!isValidCommand(match, commands[side])) commands[side] = null;
  }

  const spawned = spawnBalls(match);

  // Rotations on the same platform add; opposite directions cancel.
  const quarters = new Map();
  for (const side of ["top", "bottom"]) {
    const cmd = commands[side];
    if (!cmd) continue;
    quarters.set(cmd.platform, (quarters.get(cmd.platform) || 0) + cmd.dir);
  }

  // All platforms turn at once.
  for (const [platform, q] of quarters) {
    rotatePlatform(match, platform, q);
  }

  const movement = moveBalls(match);

  // Any platform commanded this tick — even a cancelled one — locks next phase.
  match.cooldown = [...quarters.keys()];

  const event = {
    tick: match.tick,
    commands,
    rotations: [...quarters.entries()].map(([platform, q]) => ({
      platform,
      quarters: ((q % 4) + 4) % 4,
    })),
    spawned,
    ...movement,
    score: { ...match.score },
    cooldown: match.cooldown.slice(),
  };

  match.log.push(event);

  if (
    match.tick >= TICKS ||
    match.score.top >= MERCY_SCORE ||
    match.score.bottom >= MERCY_SCORE
  ) {
    match.finished = true;
  }

  return event;
}

function matchResult(match) {
  const { top, bottom } = match.score;
  if (top === bottom) return "draw";
  return top > bottom ? "top" : "bottom";
}

// WebRTC peer connection + commit/reveal command exchange.
//
// The cloud function only relays SDP and ICE; it never sees a command. With no
// authoritative server, each tick commits a salted SHA-256 hash first and
// reveals the command once the opponent's hash is in hand. A reveal that does
// not match its hash is a protocol violation, not a chance to change the move.

const SIGNAL_URL =
  window.TWIVVY_SIGNAL_URL ||
  "https://us-central1-enotix.cloudfunctions.net/twivvy-signal";


const ICE_SERVERS = [
  { urls: "stun:stun.l.google.com:19302" },
  { urls: "stun:stun1.l.google.com:19302" },
];

const POLL_MS = 1500;

async function api(path, options = {}) {
  const res = await nativeFetch(path, {
    signal: AbortSignal.timeout(10_000),
    ...options,
    headers: { "Content-Type": "application/json", ...(options.headers || {}) },
  });
  let body = null;
  try {
    body = await res.json();
  } catch {
    body = null;
  }
  if (!res.ok) {
    const err = new Error(body?.error || `Request failed (${res.status})`);
    err.status = res.status;
    throw err;
  }
  return body;
}

/** Room codes are the alphabet the signalling service allocates from. */
const CODE_RE = /^[A-Z0-9]{4,8}$/;

/**
 * The app's directory, trailing slash included. A room code or index.html is
 * stripped, so links built inside a room still point at the site root.
 */
function basePath(pathname = window.location.pathname) {
  const parts = pathname.split("/");
  const last = parts[parts.length - 1];
  if (last === "" || last === "index.html" || CODE_RE.test(last.toUpperCase())) {
    parts[parts.length - 1] = "";
  } else {
    parts.push("");
  }
  return parts.join("/");
}

/** Room code carried by the URL, from the path (/KFUEB) or ?game=/?join=. */
function codeFromLocation(location = window.location) {
  const params = new URLSearchParams(location.search);
  const fromQuery = params.get("game") || params.get("join");
  if (fromQuery && CODE_RE.test(fromQuery.trim().toUpperCase())) {
    return fromQuery.trim().toUpperCase();
  }

  const last = location.pathname.split("/").pop() || "";
  const candidate = last.toUpperCase();
  return CODE_RE.test(candidate) ? candidate : null;
}

async function sha256Hex(text) {
  const bytes = new TextEncoder().encode(text);
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return [...new Uint8Array(digest)]
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

function randomSalt() {
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  return [...bytes].map((b) => b.toString(16).padStart(2, "0")).join("");
}

/** Canonical text form of a command, so both peers hash identical bytes. */
function encodeCommand(command) {
  if (!command) return "skip";
  return `${command.platform}:${command.dir}`;
}

function decodeCommand(text) {
  if (text === "skip") return null;
  const match = /^([0-8]):(-?1)$/.exec(text);
  if (!match) return undefined; // malformed
  return { platform: Number(match[1]), dir: Number(match[2]) };
}

const SESSION_KEY = "twivvy-session-v2:";
function readSession(code) {
  try { return JSON.parse(sessionStorage.getItem(SESSION_KEY + code)); } catch { return null; }
}

async function onlinePlayerCount() {
  const state = await api("/api/matchmaking");
  return Math.max(0, Number(state.online) || 0);
}

/** Presence in the public matchmaking pool. The same credentials are reused
 * on retries, so a lost HTTP response cannot enqueue one browser twice. */
class Matchmaker extends EventTarget {
  constructor() {
    super();
    this.ticket = randomSalt();
    this.token = randomSalt();
    this.closed = false;
    this.match = null;
  }

  _emit(type, detail = {}) {
    this.dispatchEvent(new CustomEvent(type, { detail }));
  }

  async join(name) {
    this.name = name;
    this.closed = false;
    const state = await api("/api/matchmaking", {
      method: "POST",
      body: JSON.stringify({ name, ticket: this.ticket, token: this.token }),
    });
    if (this.closed) {
      this._remove();
      return state;
    }
    this._accept(state);
    this._schedule();
    return state;
  }

  _accept(state) {
    this._emit("count", { online: Math.max(0, Number(state.online) || 0) });
    if (state.match && !this.match) {
      this.match = state.match;
      this._emit("matched", state.match);
    }
  }

  _schedule() {
    clearTimeout(this._timer);
    if (this.closed) return;
    this._timer = setTimeout(() => this._poll(), this.match ? 5000 : POLL_MS);
  }

  async _poll() {
    if (this.closed) return;
    try {
      const state = await api(`/api/matchmaking/${this.ticket}?token=${encodeURIComponent(this.token)}`);
      if (this.closed) return;
      this._accept(state);
    } catch (err) {
      if (this.closed) return;
      // A backgrounded tab ages out of the list: re-enter on the same ticket.
      if (err.status === 404 && !this.match) {
        try {
          const state = await api("/api/matchmaking", {
            method: "POST",
            body: JSON.stringify({ name: this.name, ticket: this.ticket, token: this.token }),
          });
          if (!this.closed) this._accept(state);
        } catch (retryError) {
          if (!this.closed) this._emit("error", { message: retryError.message });
        }
      } else if (!this.match) {
        this._emit("error", { message: err.message });
      }
    }
    this._schedule();
  }

  close(remove = true) {
    if (this.closed) return;
    this.closed = true;
    clearTimeout(this._timer);
    if (remove) this._remove();
  }

  _remove() {
    api(`/api/matchmaking/${this.ticket}?token=${encodeURIComponent(this.token)}`, {
      method: "DELETE",
    }).catch(() => {});
  }
}

/** Signalling remains alive after the data channel opens, so either seat can
 * rebuild its peer connection. All SDP/ICE is scoped to a server epoch. */
class Connection extends EventTarget {
  constructor() {
    super();
    this.pc = this.channel = null;
    this.role = this.code = this.token = null;
    this.myName = "Игрок";
    this.peerName = null;
    this.map = this.seed = 0;
    this.epoch = -1;
    this.closed = false;
    this._pollGeneration = 0;
    this._pendingCandidates = [];
    this._earlyCandidates = [];
    this._candidateCursor = 0;
    this._remoteSet = false;
    this._openedChannel = null;
    this._lastMessage = Date.now();
    this._lostSince = null;
    this._attempt = null;
    this._lastAttemptAt = 0;
    this._offline = () => this.reconnect();
    this._online = () => this._startPolling();
    this._pagehide = () => this.suspend();
    window.addEventListener?.("offline", this._offline);
    window.addEventListener?.("online", this._online);
    window.addEventListener?.("pagehide", this._pagehide);
    window.addEventListener?.("pageshow", this._online);
  }

  _emit(type, detail = {}) { this.dispatchEvent(new CustomEvent(type, { detail })); }

  saveGame(game) {
    this._game = game;
    this._save();
  }

  _save() {
    if (!this.code || !this.token) return;
    try {
      sessionStorage.setItem(SESSION_KEY + this.code, JSON.stringify({
        code: this.code, token: this.token, role: this.role, seed: this.seed,
        map: this.map, myName: this.myName, peerName: this.peerName,
        game: this._game, savedAt: Date.now(),
      }));
    } catch {
      if (!this._storageWarning) this._emit("storageerror");
      this._storageWarning = true;
    }
  }

  _adopt(room) {
    const role = room.role || this.role;
    Object.assign(this, { code: room.code, token: room.token || this.token,
      role, seed: room.seed ?? this.seed, map: room.map ?? this.map });
    this.myName = room.myName ||
      (role === "host" ? room.hostName : room.guestName) || this.myName;
    this.peerName = room.peerName ||
      (role === "host" ? room.guestName : room.hostName) || this.peerName;
    this._save();
  }

  async host({ seed, map, name }) {
    const room = await api("/api/rooms", { method: "POST", body: JSON.stringify({ seed, map, name, protocol: 2 }) });
    this._adopt({ ...room, role: "host", seed, map });
    await this._negotiate(room.epoch ?? 0);
    this._startPolling();
    return this.code;
  }

  async join(code, { name } = {}) {
    const room = await api(`/api/rooms/${code}/join`, { method: "POST", body: JSON.stringify({ protocol: 2, name }) });
    this._adopt({ ...room, role: "guest" });
    await this._negotiate(room.epoch ?? 0);
    this._startPolling();
    return room;
  }

  async acceptMatch(room) {
    this._adopt(room);
    await this._negotiate(room.epoch ?? 0);
    this._startPolling();
    return room;
  }

  async resume(saved) {
    this._game = saved.game;
    this._adopt(saved);
    // Retry even if the browser reloads while offline; do not claim a new seat.
    this._lostSince = saved.game?.pausedAt || Date.now();
    this._attempt = randomSalt();
    this._startPolling();
  }

  _setupPeer() {
    const pc = new RTCPeerConnection({ iceServers: ICE_SERVERS });
    this.pc = pc;
    pc.onicecandidate = event => {
      if (this.closed || this.pc !== pc || !event.candidate) return;
      this._pendingCandidates.push(event.candidate.toJSON?.() || {
        candidate: event.candidate.candidate, sdpMid: event.candidate.sdpMid,
        sdpMLineIndex: event.candidate.sdpMLineIndex,
      });
      if (!this._flushTimer) this._flushTimer = setTimeout(() => {
        this._flushTimer = null;
        this._flushCandidates();
      }, 250);
    };
    pc.onconnectionstatechange = () => {
      if (this.closed || this.pc !== pc) return;
      if (["failed", "disconnected", "closed"].includes(pc.connectionState)) this.reconnect();
    };
    pc.ondatachannel = event => {
      if (!this.closed && this.pc === pc) this._bindChannel(event.channel);
    };
    return pc;
  }

  _dropPeer() {
    const pc = this.pc, channel = this.channel;
    this.pc = this.channel = null;
    this._openedChannel = null;
    clearInterval(this._channelWatchTimer);
    clearInterval(this._heartbeat);
    clearTimeout(this._flushTimer);
    this._flushTimer = null;
    this._pendingCandidates = [];
    this._earlyCandidates = [];
    this._candidateCursor = 0;
    this._remoteSet = false;
    try { channel?.close(); pc?.close(); } catch {}
  }

  async _negotiate(epoch) {
    if (this.closed) return;
    this._dropPeer();
    this.epoch = epoch;
    this._lastAttemptAt = Date.now();
    const pc = this._setupPeer();
    if (this.role !== "host") return;
    this._bindChannel(pc.createDataChannel("twivvy", { ordered: true }));
    const offer = await pc.createOffer();
    if (this.pc !== pc) return;
    await pc.setLocalDescription(offer);
    if (this.pc !== pc) return;
    await this._signal({ description: { type: offer.type, sdp: offer.sdp } }, epoch);
  }

  _signal(fields, epoch = this.epoch) {
    return api(`/api/rooms/${this.code}/signal`, {
      method: "POST", body: JSON.stringify({ token: this.token, epoch, ...fields }),
    });
  }

  async _flushCandidates() {
    if (!this._pendingCandidates.length || this.closed) return;
    const epoch = this.epoch;
    const candidates = this._pendingCandidates.splice(0);
    try { await this._signal({ candidates }, epoch); }
    catch {
      if (epoch === this.epoch && !this.closed) this._pendingCandidates.unshift(...candidates);
    }
  }

  async _acceptRemote(description) {
    if (this._remoteSet || !this.pc) return;
    const pc = this.pc, epoch = this.epoch;
    await pc.setRemoteDescription(description);
    if (this.pc !== pc) return;
    this._remoteSet = true;
    for (const candidate of this._earlyCandidates.splice(0)) {
      try { await pc.addIceCandidate(candidate); } catch {}
    }
    if (description.type === "offer") {
      const answer = await pc.createAnswer();
      if (this.pc !== pc) return;
      await pc.setLocalDescription(answer);
      if (this.pc !== pc) return;
      await this._signal({ description: { type: answer.type, sdp: answer.sdp } }, epoch);
    }
  }

  _bindChannel(channel) {
    clearInterval(this._channelWatchTimer);
    this.channel = channel;
    const current = () => !this.closed && channel === this.channel;
    channel.onopen = () => this._notifyChannelOpen(channel);
    this._channelWatchTimer = setInterval(channel.onopen, POLL_MS);
    queueMicrotask(channel.onopen);
    channel.onclose = () => { if (current()) this.reconnect(); };
    channel.onmessage = event => {
      if (!current()) return;
      this._notifyChannelOpen(channel);
      this._lastMessage = Date.now();
      let msg;
      try { msg = JSON.parse(event.data); } catch { return; }
      if (msg?.type === "ping") { this.send({ type: "pong" }); return; }
      if (msg?.type === "pong") return;
      if (msg?.type === "leaving") { this.reconnect(); return; }
      if (typeof msg?.type === "string") this._emit("message", msg);
    };
  }

  _notifyChannelOpen(channel = this.channel) {
    if (this.closed || !channel || channel !== this.channel || channel.readyState !== "open") return false;
    if (this._openedChannel === channel) return true;
    this._openedChannel = channel;
    this._lastMessage = Date.now();
    this._lostSince = null;
    this._attempt = null;
    clearInterval(this._channelWatchTimer);
    clearInterval(this._heartbeat);
    this._heartbeat = setInterval(() => {
      if (Date.now() - this._lastMessage > 5000) this.reconnect();
      else this.send({ type: "ping" });
    }, 1000);
    this._emit("open");
    return true;
  }

  send(message) {
    if (this.closed || this.channel?.readyState !== "open") return false;
    try { this.channel.send(JSON.stringify(message)); return true; }
    catch { this.reconnect(); return false; }
  }

  reconnect() {
    if (this.closed) return;
    this._lostSince ??= Date.now();
    this._emit("peerlost", { since: this._lostSince });
    this._dropPeer();
    this._attempt ??= randomSalt();
    this._startPolling();
  }

  _startPolling() {
    if (this.closed || !this.code) return;
    this._stopPolling();
    const generation = this._pollGeneration;
    const current = () => !this.closed && generation === this._pollGeneration;
    const poll = async () => {
      if (!current()) return;
      try {
        if (this._attempt) {
          const attempt = this._attempt;
          const room = await api(`/api/rooms/${this.code}/resume`, {
            method: "POST", body: JSON.stringify({ token: this.token, attempt }),
          });
          if (!current()) return;
          this._adopt(room);
          this._attempt = null;
          this._lastAttemptAt = Date.now();
          await this._negotiate(room.epoch);
          if (!current()) return;
        }
        const epoch = this.epoch;
        const state = await api(`/api/rooms/${this.code}?token=${encodeURIComponent(this.token)}&since=${this._candidateCursor}&epoch=${epoch}`);
        if (!current()) return;
        if (typeof state.peerName === "string" && state.peerName && state.peerName !== this.peerName) {
          this.peerName = state.peerName;
          this._save();
          this._emit("peername", { name: this.peerName });
        }
        if (state.epoch !== this.epoch) {
          this._lostSince ??= Date.now();
          this._emit("peerlost", { since: this._lostSince });
          this._lastAttemptAt = Date.now();
          await this._negotiate(state.epoch);
          if (!current()) return;
        }
        if (state.peerAbsentAt && this.channel?.readyState !== "open") {
          this._lostSince ??= state.peerAbsentAt;
          this._emit("peerlost", { since: this._lostSince });
        }
        if (state.peerJoined) this._emit("guestjoined");
        if (state.description && !this._remoteSet) await this._acceptRemote(state.description);
        if (!current()) return;
        for (const candidate of state.candidates || []) {
          if (!this._remoteSet) this._earlyCandidates.push(candidate);
          else try { await this.pc.addIceCandidate(candidate); } catch {}
        }
        this._candidateCursor = state.candidateCount || 0;
        await this._flushCandidates();
        // Lost SDP uploads / ICE failure cannot leave a dead negotiation forever.
        if (this.channel?.readyState !== "open" && Date.now() - this._lastAttemptAt > 20_000) {
          this._lastAttemptAt = Date.now();
          this._attempt = randomSalt();
        }
      } catch (err) {
        if (!current()) return;
        if ([403, 404, 410].includes(err.status)) {
          this._emit("expired", { message: "Партия прервана: соперник отсутствовал более 30 минут." });
          this.close(false);
          return;
        }
        // Transient signalling failure must not stop a healthy P2P match.
      }
      if (current()) this._pollTimer = setTimeout(poll, this.channel?.readyState === "open" ? 5000 : POLL_MS);
    };
    this._pollTimer = setTimeout(poll, 200);
  }

  _stopPolling() {
    this._pollGeneration++;
    clearTimeout(this._pollTimer);
  }

  suspend() {
    if (this.closed || !this.token) return;
    this.send({ type: "leaving" });
    this._emit("peerlost", { since: Date.now() });
    this._save();
    nativeFetch(`/api/rooms/${this.code}/presence`, {
      method: "POST", headers: { "Content-Type": "application/json" }, keepalive: true,
      body: JSON.stringify({ token: this.token, epoch: this.epoch }),
    }).catch(() => {});
    this._dropPeer();
    this._stopPolling();
    this._attempt = randomSalt();
  }

  inviteLink() { return new URL(basePath() + this.code, window.location.href).toString(); }

  close(removeRoom = true) {
    if (this.closed) return;
    if (removeRoom) api(`/api/rooms/${this.code}?token=${encodeURIComponent(this.token)}`, { method: "DELETE" }).catch(() => {});
    this.closed = true;
    this._stopPolling();
    this._dropPeer();
    window.removeEventListener?.("offline", this._offline);
    window.removeEventListener?.("online", this._online);
    window.removeEventListener?.("pagehide", this._pagehide);
    window.removeEventListener?.("pageshow", this._online);
    try { sessionStorage.removeItem(SESSION_KEY + this.code); } catch {}
  }
}

// Resumable deterministic match. Private choices never enter sync messages.

const ABSENCE_MS = 30 * 60_000;
const copy = value => JSON.parse(JSON.stringify(value));
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const uid = () => crypto.randomUUID();

function freshRound(remaining) {
  return { remaining, selection: null, locked: false, salt: uid(), hash: null,
    peerHash: null, peerReveal: null };
}

/** Rebuild rather than trust a remote board: history must extend our exact
 * prefix, and an interrupted resolve may add at most one verifiable round. */
async function reconcile(local, remote, side, decideMs = DECIDE_MS) {
  if (!remote || remote.id !== local.id || remote.map !== local.map ||
      !Array.isArray(remote.log) || remote.log.length > TICKS ||
      Math.abs(remote.log.length - local.match.log.length) > 1) throw new Error("Different match history");
  const own = local.match.log;
  for (let i = 0; i < Math.min(own.length, remote.log.length); i++) {
    if (!same(own[i], remote.log[i])) throw new Error("Conflicting match history");
  }
  const ahead = remote.log.length > own.length;
  const log = ahead ? remote.log : own;
  const proofs = ahead ? remote.proofs : local.proofs;
  const match = createMatch(local.map);
  for (let i = 0; i < log.length; i++) {
    const event = log[i];
    if (!event?.commands) throw new Error("Missing commands");
    const replayed = resolveTick(match, event.commands.top, event.commands.bottom);
    if (!same(replayed, event)) throw new Error("Invalid match history");
    if (i >= own.length) {
      const proof = proofs?.[i];
      for (const player of ["top", "bottom"]) {
        const p = proof?.[player];
        if (!p || p.command !== encodeCommand(event.commands[player]) ||
            await sha256Hex(`${i + 1}|${p.command}|${p.salt}`) !== p.hash) throw new Error("Invalid move proof");
      }
      if (!local.round.locked || local.round.hash !== proof[side].hash ||
          (local.round.peerHash && local.round.peerHash !== proof[side === "top" ? "bottom" : "top"].hash)) {
        throw new Error("Resolved move differs from saved commitment");
      }
    }
  }
  const remoteLeft = Number(remote.remaining);
  if (!Number.isFinite(remoteLeft) || remoteLeft < 0 || remoteLeft > decideMs) throw new Error("Invalid timer");
  const round = ahead ? freshRound(remoteLeft) : copy(local.round);
  if (remote.log.length === own.length) round.remaining = Math.min(round.remaining, remoteLeft);
  return { match, proofs: copy(proofs), round };
}

class MatchSession {
  constructor(connection, options = {}) {
    this.connection = connection;
    this.side = connection.role === "host" ? "bottom" : "top";
    this.decideMs = options.decideMs || DECIDE_MS;
    this.callbacks = options;
    const saved = options.saved;
    this.id = saved?.id || (this.side === "bottom" ? uid() : null);
    this.map = saved?.map ?? connection.map;
    this.match = saved?.match || createMatch(this.map);
    this.proofs = saved?.proofs || [];
    this.round = saved?.round || freshRound(this.decideMs);
    this.pausedAt = saved?.pausedAt ?? (saved ? saved.savedAt : null);
    this.ended = saved?.ended || false;
    this.phase = "paused";
    this.generation = 0;
    this._onMessage = e => this._message(e.detail).catch(err => this._fail(err));
    connection.addEventListener("message", this._onMessage);
    this._watch = setInterval(() => this._watchdog(), 250);
    this._save();
  }

  remaining() {
    return this.phase === "decide" ? Math.max(0, this.deadline - Date.now()) : this.round.remaining;
  }

  snapshot() {
    return copy({ id: this.id, map: this.map, match: this.match, proofs: this.proofs,
      round: { ...this.round, remaining: this.remaining() }, pausedAt: this.pausedAt,
      ended: this.ended, savedAt: Date.now() });
  }

  _save() { this.connection.saveGame(this.snapshot()); }

  publicState() {
    return { id: this.id, map: this.map, log: this.match.log, proofs: this.proofs,
      remaining: this.remaining(), ready: this.phase === "sync" };
  }

  choose(selection) {
    if (this.phase !== "decide" || this.round.locked) return;
    this.round.selection = isValidCommand(this.match, selection) ? selection : null;
    this._save();
  }

  pause(since = Date.now()) {
    if (this.ended) return;
    // Disabling interaction settles any in-flight drag and saves its choice.
    this.callbacks.lock?.();
    this.round.remaining = this.remaining();
    this.pausedAt ??= since;
    this.phase = "paused";
    this.generation++;
    this._resolving = null;
    this._plan = null;
    this._planning = false;
    this._save();
    this.callbacks.paused?.();
  }

  connected() {
    if (this.ended) { this.callbacks.finished?.(this.ended === true ? null : this.ended); return; }
    this.pause();
    this.phase = "sync";
    this.syncStarted = Date.now();
    this.connection.send({ type: "sync-request" });
    this._sendState();
  }

  _sendState() { this.connection.send({ type: "sync-state", state: this.publicState() }); }

  async _apply(remote) {
    const generation = this.generation;
    const reconciled = await reconcile(this.snapshot(), remote, this.side, this.decideMs);
    if (generation !== this.generation) return false;
    Object.assign(this, reconciled);
    this._save();
    await this.callbacks.restore?.(this.match, this.round.selection);
    return generation === this.generation;
  }

  async _message(msg) {
    if (this.ended) return;
    if (msg.type === "sync-request") { this._sendState(); return; }
    if (msg.type === "sync-state" && msg.state?.ready && this.side === "bottom" && this.phase === "sync" && !this._planning && !this._plan) {
      this._planning = true;
      const generation = this.generation;
      try {
        // A fresh guest learns the host's match identity without seeing choices.
        const state = msg.state?.id === null && !msg.state?.log?.length
          ? { ...msg.state, id: this.id, map: this.map } : msg.state;
        if (!await this._apply(state)) return;
        this._plan = uid();
        this.connection.send({ type: "sync-plan", nonce: this._plan, state: this.publicState() });
      } finally { if (generation === this.generation) this._planning = false; }
      return;
    }
    if (msg.type === "sync-plan" && this.side === "top" && ["sync", "paused"].includes(this.phase)) {
      if (!this.id && !this.match.tick) {
        this.id = msg.state.id;
        this.map = msg.state.map;
        this.match = createMatch(this.map);
      }
      this.phase = "sync";
      if (!await this._apply(msg.state)) return;
      this._plan = msg.nonce;
      this.connection.send({ type: "sync-ready", nonce: this._plan });
      return;
    }
    if (msg.type === "sync-ready" && this.side === "bottom" && this.phase === "sync" && msg.nonce === this._plan) {
      this.connection.send({ type: "sync-go", nonce: this._plan });
      this._go();
      return;
    }
    if (msg.type === "sync-go" && this.side === "top" && this.phase === "sync" && msg.nonce === this._plan) {
      this._go();
      return;
    }
    if (msg.game !== this.id || msg.tick !== this.match.tick + 1) return;
    if (msg.type === "commit") {
      if (typeof msg.hash !== "string" || !/^[a-f0-9]{64}$/.test(msg.hash)) throw new Error("Invalid commitment");
      if (this.round.peerHash && this.round.peerHash !== msg.hash) throw new Error("Changed commitment");
      this.round.peerHash = msg.hash;
      this._save();
      await this._exchange();
    } else if (msg.type === "reveal") {
      if (!this.round.locked || !this.round.peerHash) return;
      this.round.peerReveal = { command: msg.command, salt: msg.salt };
      this._save();
      await this._exchange();
    }
  }

  _go() {
    if (this.match.finished) { this.finish(null); return; }
    this.pausedAt = null;
    this.phase = this.round.locked ? "exchange" : "decide";
    this.deadline = Date.now() + this.round.remaining;
    this.exchangeStarted = Date.now();
    this._save();
    this.callbacks.active?.(!this.round.locked);
    if (this.round.locked) this._commit();
  }

  async _commit() {
    const generation = this.generation, round = this.round;
    this.callbacks.lock?.();
    round.remaining = 0;
    round.locked = true;
    this.phase = "exchange";
    this.exchangeStarted = Date.now();
    this._save(); // Salt and immutable choice survive refresh even during digest.
    round.hash = await sha256Hex(`${this.match.tick + 1}|${encodeCommand(round.selection)}|${round.salt}`);
    if (generation !== this.generation || this.round !== round) return;
    this._save();
    this.connection.send({ type: "commit", game: this.id, tick: this.match.tick + 1, hash: round.hash });
    await this._exchange();
  }

  async _exchange() {
    const round = this.round, generation = this.generation;
    if (this.phase !== "exchange" || !round.hash || !round.peerHash || this._resolving) return;
    this.connection.send({ type: "reveal", game: this.id, tick: this.match.tick + 1,
      command: encodeCommand(round.selection), salt: round.salt });
    if (!round.peerReveal) return;
    const token = {};
    this._resolving = token;
    const peer = round.peerReveal;
    const hash = await sha256Hex(`${this.match.tick + 1}|${peer.command}|${peer.salt}`);
    if (generation !== this.generation || round !== this.round) return;
    const command = decodeCommand(peer.command);
    if (hash !== round.peerHash || command === undefined) throw new Error("Invalid reveal");
    const other = this.side === "top" ? "bottom" : "top";
    const commands = { [this.side]: round.selection, [other]: command };
    const before = copy(this.match);
    const event = resolveTick(this.match, commands.top, commands.bottom);
    this.proofs.push({ [this.side]: { hash: round.hash, salt: round.salt, command: encodeCommand(round.selection) },
      [other]: { ...peer, hash } });
    this.round = freshRound(this.decideMs);
    this.phase = "animate";
    this._save(); // Persist logical result BEFORE any await/animation.
    await this.callbacks.resolved?.(event, before, this.match);
    if (generation !== this.generation) return;
    this._resolving = null;
    // Use the same barrier after every turn: neither peer can start alone.
    this._plan = null;
    this.phase = "sync";
    this.syncStarted = Date.now();
    this._sendState();
    this.connection.send({ type: "sync-request" });
  }

  _watchdog() {
    if (this.ended) return;
    if (this.pausedAt !== null && Date.now() - this.pausedAt >= ABSENCE_MS) {
      this.finish("Партия прервана: соперник отсутствовал более 30 минут.");
      this.connection.close();
      return;
    }
    if (this.phase === "decide") {
      this.callbacks.timer?.(this.remaining() / this.decideMs);
      this._save();
      if (!this.remaining()) this._commit().catch(err => this._fail(err));
    } else if ((this.phase === "exchange" && Date.now() - this.exchangeStarted > 6000) ||
               (this.phase === "sync" && Date.now() - this.syncStarted > 10_000)) {
      // A timeout is a pause, NEVER a skipped opponent move.
      this.connection.reconnect();
    }
  }

  finish(reason) {
    this.ended = reason || true;
    this.phase = "ended";
    this.generation++;
    this._save();
    this.callbacks.finished?.(reason);
  }

  _fail(err) {
    console.error("session protocol", err);
    this.finish("Не удалось согласовать сохранённую партию.");
  }

  dispose() {
    this.generation++;
    clearInterval(this._watch);
    this.connection.removeEventListener("message", this._onMessage);
  }
}

